    """In one row, fill each background cell lying between two fg cells with fill."""
    from collections import Counter
    if bg is None:
        bg = Counter(row).most_common(1)[0][0]
    if fg is None:
        fg = {v for v in row if v != bg}
    row = row[:]
    idx = [j for j, v in enumerate(row) if v in fg]
    for a, b in zip(idx, idx[1:]):
        for j in range(a + 1, b):
            if row[j] == bg:
                row[j] = fill
    return row

def fill_row_gaps(grid, fill):
    """Every row: fill background cells between consecutive non-background cells with fill."""
    return [fill_gaps_row(row, fill) for row in grid]
